let toastTimer,returnFocus,confirmationTimer;
const project = () => state.projects.find(p=>p.name===state.project&&(!state.hostId||state.hostId==='all'||!p.hostId||p.hostId===state.hostId));
function activeHostId(){return project()?.hostId||state.hostId||'local';}
function scopeKey(name=state.project,hostId=activeHostId()){return hostId+'::'+name;}
function findTask(id){const matches=scopedTasks().filter(task=>task.id===id);return matches.length===1?matches[0]:null;}
const mode = () => project()?.mode || state.rosterView;
const scopedTasks = () => state.tasks.filter(t => (state.project==='all'||t.project===state.project)&&(!t.hostId||activeHostId()==='all'||t.hostId===activeHostId()));
const readonly = () => state.project==='all'||Boolean(state.hosts?.find(host=>host.id===activeHostId()&&host.status!=='online'));
const inboxCount = () => typeof fleetInboxItems==='function'?fleetInboxItems().length:(((state.project==='all'||mode()==='scrum')&&!state.emptyProjects?.has(scopeKey()) ? Number(!state.designDecision)+Number(!state.questionAnswer&&!state.cancelledQuestion) : 0) + scopedTasks().filter(t=>t.status==='attention'||(t.mode==='slp'&&t.status==='ready')).length);
const money = n => '$'+n.toFixed(2);
const statusTone = s => ({running:'cyan',completed:'green',accepted:'green',ready:'green',attention:'amber',waiting:'amber',red:'red'}[s]||'');
const statusLabel = s => ({running:'Running',completed:'Completed',accepted:'Accepted',ready:'Ready to accept',attention:'Needs you',waiting:'Awaiting approval',queued:'Waiting',idle:'Idle'}[s]||s);
function agent(id){const a={...(agentDefinitions[id]||agentDefinitions.dev)};if(id==='lead'&&mode()==='slp')a.name='Lead';if(id==='ux'&&state.designDecision)a.status=state.designDecision==='changes'?'running':'completed';if(id==='gate'&&state.designDecision)a.status=state.designDecision==='changes'?'waiting':'completed';const t=scopedTasks().find(t=>t.id===a.task);if(t?.status==='accepted')a.status='completed';if(id!=='owner'&&(state.emptyProjects?.has(scopeKey())||state.retiredSeats?.has(scopeKey()+':'+id))){a.status='queued';delete a.task;a.subtitle=id==='supervisor'?'Start in Paseo New Chat':id==='lead'?'Spawned by Supervisor':'No run started';}return a;}
function notify(text, error=false){const el=$('#toast');el.textContent=text;el.className='toast'+(error?' error-toast':'');el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.hidden=true;},4200);}
function log(text,task='',tone='cyan',glyph='activity'){state.events.unshift({text,task,tone,icon:glyph,time:'Just now'});state.lastAction=Date.now();}
function refreshIcons(root=document){$$('[data-icon]',root).forEach(el=>{el.innerHTML=icon(el.dataset.icon);});}
function openModal(title,body,wide=false){const modal=$('#modal');returnFocus=document.activeElement;$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;modal.classList.toggle('wide',wide);if(!modal.open)modal.showModal();const first=$('input,textarea,select,button', $('#modal-body'));if(first)first.focus();}
function closeModal(){const modal=$('#modal');if(modal.open)modal.close();clearTimeout(confirmationTimer);state.confirmation=null;const candidate=returnFocus?.isConnected?returnFocus:$('.nav-item.active');candidate?.focus();}
function heading(title,description,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
function modeControls(){return `<span class="mode-readonly-badge" title="Execution mode is locked during active runs. Change in Settings → Project.">${icon('flow')}<span>${mode()==='scrum'?'Agile Scrum':'SLP'}</span></span>${button(typeof paseoSupervisorVacant==='function'&&paseoSupervisorVacant()?'Start Supervisor':'Open Supervisor','open-supervisor','','ghost','external')}`;}
function syncShell(){
 $('#breadcrumb').textContent=readonly()?'All projects':state.project;
 $('#nav-task-count').textContent=scopedTasks().length;$('#nav-inbox-count').textContent=inboxCount();$('#nav-inbox-count').hidden=inboxCount()===0;
 $$('.nav-item[data-nav]').forEach(el=>{el.classList.toggle('active',el.dataset.nav===state.page);if(el.dataset.nav===state.page)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
 $('#app').classList.remove('menu-open');
 const titles={overview:['All projects','Across your connected Hosts.'],hosts:['Hosts','The machines behind your projects.'],flow:['Execution overview','Your team, their work, and the path forward.'],tasks:['Task board','From a clear contract to a verified result.'],inbox:['Needs you','Decisions that keep your team moving.'],models:['Agents & Models','The right model for every role.'],activity:['Activity','A traceable history of the work.'],integrations:['Integrations','Tools, skills, and connections for your agents.'],design:['Open Design','Keep design intent close to delivery.'],vault:['Private Vault','Your private configuration, across machines.'],settings:['Project settings','Workspace configuration and diagnostics.'],daemon:['Daemon settings','']};
 const [title,sub]=titles[state.page];$('.page-heading').outerHTML=heading(title,sub,['flow','models'].includes(state.page)?modeControls():badge('Sample workspace',''));
}
function render(){syncShell();const views={flow:renderFlow,tasks:renderTasks,inbox:renderInbox,models:renderModels,activity:renderActivity,integrations:renderIntegrations,design:renderDesign,vault:renderVault,settings:renderSettings,daemon:()=>renderDaemonSettings()};$('#view').innerHTML=(views[state.page]||renderFlow)();refreshIcons();}
function navigate(page){state.page=page;state.filter='all';state.search='';render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
function stats(){const tasks=scopedTasks();const activeIds=new Set(tasks.filter(t=>t.status==='running').map(t=>t.agent));if(tasks.some(t=>t.status==='running'))activeIds.add('lead');const accepted=tasks.filter(t=>t.status==='accepted').length;return `<div class="stats"><div class="stat"><div class="label"><span class="dot cyan"></span>Active agents</div><div class="value"><strong>${activeIds.size}</strong><span class="note">working in parallel</span></div></div><div class="stat"><div class="label">Tasks in workspace</div><div class="value"><strong>${tasks.length}</strong><span class="note">${accepted} accepted</span></div></div><div class="stat"><div class="label"><span class="dot amber"></span>Needs your attention</div><div class="value"><strong class="amber">${inboxCount()}</strong><span class="note">${inboxCount()?'decisions pending':'all clear'}</span></div></div><div class="stat"><div class="label">Metered cost</div><div class="value"><strong>${money(tasks.reduce((n,t)=>n+t.cost,0))}</strong><span class="note">sample usage</span></div></div></div>`;}
function node(id,authority=false){const a=agent(id),tone=statusTone(a.status);return `<button class="node ${a.status==='running'?'running':''} ${['queued','waiting'].includes(a.status)?'locked':''} ${a.status==='attention'?'waiting':''} ${state.selected===id?'selected':''}" data-agent="${id}" aria-label="${esc(a.name)}, ${statusLabel(a.status)}" aria-pressed="${state.selected===id}"><span class="node-top"><span class="role-avatar ${tone}">${a.initials}</span>${authority?`<strong>${esc(a.name)}</strong>${id==='owner'?'<span class="you">You</span>':''}`:`<span class="${tone}">${icon(a.status==='completed'?'check':a.status==='queued'?'lock':a.status==='attention'?'clock':'agents')}</span>`}</span><span class="od-field">${authority?'':`<strong>${esc(a.short||a.name)}</strong>`}<span class="model">${esc(a.model)}</span></span><span class="node-foot ${tone}"><span class="dot"></span>${id==='owner'?'Product decisions':statusLabel(a.status)}<span class="spacer"></span>${a.task?`<span class="node-id">${a.task.replace('SCR-','#')}</span>`:''}</span></button>`;}
function authorityGraph(){return `<div class="authority">${node('owner',true)}<div class="arrow" aria-hidden="true"></div>${node('supervisor',true)}<div class="arrow" aria-hidden="true"></div>${node('lead',true)}</div>`;}
function scrumGraph(){return `${authorityGraph()}<div class="dispatch-rail">Specialist execution pipeline</div><div class="flow-stages"><div class="branch" aria-hidden="true"></div><div class="merge" aria-hidden="true"></div><div class="stage"><div class="stage-label"><b>01</b> PLANNING</div>${node('pm')}</div><div class="stage design"><div class="stage-label"><b>02</b> DESIGN ∥ ARCH</div>${node('ux')}${node('architect')}</div><div class="stage"><div class="stage-label"><b>03</b> READINESS</div>${node('gate')}</div><div class="stage"><div class="stage-label"><b>04</b> DELIVERY</div>${node('dev')}</div><div class="stage"><div class="stage-label"><b>05</b> VERIFICATION</div>${node('qa')}</div></div><div class="loop"><span class="loop-line" aria-hidden="true"></span><span>↶ QA & fix loop · ${state.fixRounds}/${state.qaAllowance} rounds</span></div>`;}
function slpGraph(){return `${authorityGraph()}<div class="dispatch-rail">Bounded contracts · independent task workspaces</div><div class="slp-workers">${['peer-1','peer-2','peer-3'].map(id=>node(id)).join('')}</div><div class="slp-gate">${badge('Contract','')}${icon('arrow')}${badge('Attempt','cyan')}${icon('arrow')}${badge('Gate','green')}${icon('arrow')}${badge('Owner Accept','amber')}</div>`;}
function banner(){if(inboxCount()===0)return '';const scrum=mode()==='scrum';return `<div class="attention-banner">${icon('clock')}<div class="od-fill"><strong>${scrum&&!state.designDecision?'Your team is waiting on a design decision':`${inboxCount()} item${inboxCount()===1?'':'s'} need your attention`}</strong><p>${scrum&&!state.designDecision?'Design revision 3 is ready. Independent work can continue.':'Review questions, blockers, and green attempts.'}</p></div>${button(scrum&&!state.designDecision?'Review design':'View inbox',scrum&&!state.designDecision?'review':'inbox','','','arrow')}</div>`;}
function renderFlow(){if(readonly())return `${stats()}<div class="list-grid">${state.projects.map(p=>`<article class="panel content-card"><div class="card-top"><span class="project-avatar">${esc(p.name.slice(0,2))}</span>${badge(p.mode==='scrum'?'Agile Scrum':'SLP','cyan')}</div><h2>${esc(p.name)}</h2><p>${p.mode==='scrum'?'Design · Owner approval needed':'Verification · Tasks in progress'}</p><div class="data-list"><div><dt>Tasks</dt><dd>${state.tasks.filter(t=>t.project===p.name).length}</dd></div></div>${button('Open project','select-project',`data-project="${esc(p.name)}"`,'','arrow')}</article>`).join('')}</div>${renderRecent()}`;
 return `${stats()}${banner()}<div class="workspace-grid" style="${!state.inspector?'grid-template-columns:1fr':''}"><div><section class="panel"><div class="panel-head"><div class="tabs"><button class="tab ${state.graphTab==='workflow'?'active':''}" data-graph-tab="workflow">Workflow</button><button class="tab ${state.graphTab==='agents'?'active':''}" data-graph-tab="agents">Authority</button></div><div class="od-row"><button class="icon-btn" data-action="compact" aria-label="${state.compact?'Expand node details':'Compact node details'}" title="Toggle node detail">${icon('agents')}</button><button class="icon-btn" data-action="toggle-inspector" aria-label="Toggle agent details" title="Agent details">${icon('info')}</button></div></div><div class="graph-meta"><div class="od-row">${badge(mode()==='scrum'?'Agile Scrum':'SLP','',false)}<span>${mode()==='scrum'?'Design & architecture':'Contract execution'}</span></div><span class="run">${mode()==='scrum'?'sample-run-008':'sample-slp-003'}</span></div><div class="graph-canvas ${state.compact?'compact':''} ${state.graphTab==='agents'?'agent-only':''}" id="graph-canvas" style="font-size:${state.zoom}%">${mode()==='scrum'?scrumGraph():slpGraph()}</div><div class="graph-footer"><div class="legend"><span><i class="dot cyan"></i>Running</span><span><i class="dot green"></i>Completed</span><span><i class="dot amber"></i>Needs you</span><span><i class="dot muted"></i>Waiting</span></div><div class="graph-controls"><button data-action="zoom-out" aria-label="Zoom out">${icon('minus')}</button><span class="zoom">${state.zoom}%</span><button data-action="zoom-in" aria-label="Zoom in">${icon('plus')}</button><button data-action="fit" aria-label="Fit graph">${icon('fit')}</button></div></div></section>${renderRecent()}</div>${state.inspector?renderInspector():''}</div>`;}
function renderRecent(){return `<section class="panel activity"><div class="panel-head"><h2>Recent activity</h2><button class="text-btn" data-nav="activity">View all ${icon('arrow')}</button></div><div class="activity-list">${state.events.slice(0,3).map(e=>`<div class="activity-row"><span class="event-icon ${e.tone}">${icon(e.icon)}</span><div class="od-fill"><span>${esc(e.text)}</span>${e.task?` <span class="mono muted">${esc(e.task)}</span>`:''}</div><time>${esc(e.time)}</time></div>`).join('')}</div></section>`;}
function renderInspector(){const a=agent(state.selected);const t=scopedTasks().find(t=>t.id===a.task);return `<aside class="panel inspector" aria-label="Selected agent details"><div class="inspector-head"><span class="eyebrow">AGENT DETAILS</span><button class="icon-btn" data-action="toggle-inspector" aria-label="Close agent details">${icon('close')}</button></div><div class="agent-title"><span class="role-avatar ${statusTone(a.status)}">${a.initials}</span><div><h2>${esc(a.name)}</h2><p>${esc(a.subtitle)}</p></div></div><div class="status-line ${statusTone(a.status)}"><span class="dot"></span>${a.status==='attention'?'Waiting for your approval':statusLabel(a.status)}</div><dl class="data-list"><div><dt>Provider</dt><dd>${esc(a.provider)}</dd></div><div><dt>Model</dt><dd>${esc(a.model)}</dd></div><div><dt>Thinking</dt><dd>${state.selected==='owner'?'—':'High'}</dd></div><div><dt>Session</dt><dd class="mono">${state.selected==='owner'?'You':`sample-${state.selected}-03`}</dd></div>${state.selected==='lead'?'<div><dt>Context</dt><dd>42k / 128k</dd></div><div><dt>Handoff</dt><dd>Normal · 2 queued</dd></div>':''}</dl><div class="rule"></div><div class="section-title">${t?'CURRENT TASK':'RESPONSIBILITY'}</div><div class="task-preview">${t?`<span class="task-id">#${t.id}</span><h3>${esc(t.title)}</h3><p>Attempt ${Math.max(1,t.attempts.length)} of 3 · ${t.attempts.includes('green')?'Gate green':'Gate pending'}</p>`:`<h3>${esc(a.subtitle)}</h3><p>${state.selected==='owner'?'Set direction, resolve questions, and accept verified work.':'Coordinates bounded work through the Factory lifecycle.'}</p>`}</div><div class="section-title">${t?'ARTIFACTS':'WORKSPACE'}</div><div class="artifact-list">${(t?t.artifact.split(' · '):['Project overview']).map(file=>`<button class="artifact" data-action="artifact" data-file="${esc(file)}">${icon('file')}<span class="od-fill">${esc(file)}</span>${icon('external')}</button>`).join('')}</div>${state.selected==='ux'&&!state.designDecision?button('Review design','review','','primary','design'):t?button('Inspect task','task',`data-task="${t.id}"`,'primary','tasks'):button('View tasks','tasks','','','tasks')}<button class="text-btn" data-action="open-agent" data-agent-id="${state.selected}">Open in Paseo ${icon('external')}</button></aside>`;}
const columns=[['queued','Queued','muted','No queued contracts'],['running','In Progress','cyan','No active runs'],['attention','Needs Attention','amber','No blockers or red gates'],['ready','Ready to Accept','green','Nothing awaiting acceptance'],['accepted','Accepted','green','No accepted tasks yet']];
function attemptTrail(t){return `<span class="attempts">${t.attempts.length?t.attempts.map(s=>`<i class="dot ${s==='green'?'green':s==='red'?'red':'cyan'}" aria-label="${s}"></i>`).join(''):'No attempts'}<span class="spacer"></span>${t.attempts.length?'#'+t.attempts.length+'/3':''}</span>`;}
function taskCard(t){return `<article class="task-card"><button data-action="task" data-task="${t.id}" aria-label="Inspect ${t.id}"><span class="od-row"><span class="mono muted" style="font-size:10px">#${t.id}</span><span class="spacer"></span>${t.status==='accepted'?`<span class="green">${icon('check')}</span>`:''}</span><h3 class="od-clamp-2">${esc(t.title)}</h3><span class="task-meta">${badge((t.mode==='scrum'?'Scrum':'SLP')+' · '+t.role)}${readonly()?badge(t.project):''}</span>${attemptTrail(t)}</button>${t.blocker?`<p class="small amber" style="margin:12px 0;font-size:10px">${esc(t.blocker)}</p>`:''}<div class="od-row" style="margin-top:12px">${button('Open Peer','open-agent',`data-agent-id="${t.agent}"`,'ghost')}${t.status==='ready'?button('Accept #'+t.attempts.length,'accept',`data-task="${t.id}" ${readonly()?'disabled':''}`,'','check'):''}</div></article>`;}
function renderTasks(){const all=scopedTasks();const tasks=all.filter(t=>(state.filter==='all'||t.status===state.filter||t.mode===state.filter)&&(!state.search||(t.title+' '+t.id+' '+t.role+' '+t.project).toLowerCase().includes(state.search.toLowerCase())));const shown=columns.filter(([id])=>state.filter==='all'||['slp','scrum'].includes(state.filter)||state.filter===id);return `${stats()}<div class="toolbar"><div class="filters"><button class="filter ${state.filter==='all'?'active':''}" data-filter="all">All <span class="muted">${all.length}</span></button>${(readonly()?[['slp','SLP'],['scrum','Agile Scrum']]:columns.map(c=>[c[0],c[1]])).map(([id,label])=>`<button class="filter ${state.filter===id?'active':''}" data-filter="${id}">${label} <span class="muted">${all.filter(t=>t.status===id||t.mode===id).length}</span></button>`).join('')}</div><label class="sr-only" for="task-search">Search tasks</label><input class="search-input" id="task-search" placeholder="Search tasks…" value="${esc(state.search)}"></div>${tasks.length?`<div class="kanban" style="${shown.length<3?'grid-template-columns:repeat('+shown.length+',minmax(0,1fr))':''}">${shown.map(([id,name,tone,empty])=>`<section class="kanban-column ${tasks.some(t=>t.status===id)?'':'empty-column'}"><h2 class="column-head"><span class="dot ${tone}"></span>${name}<span class="count">${tasks.filter(t=>t.status===id).length}</span></h2>${tasks.filter(t=>t.status===id).map(taskCard).join('')||`<p class="empty small">${empty}</p>`}</section>`).join('')}</div><div class="mobile-empty">EMPTY STAGES · ${shown.filter(([id])=>!tasks.some(t=>t.status===id)).map(c=>c[1]).join(' · ')||'None'}</div>`:'<div class="panel empty"><h3>No matching tasks</h3><p>Try another search or select All.</p></div>'}`;}
function showTask(id){const t=findTask(id);if(!t)return;openModal(`${t.id} — detail`,`${badge(statusLabel(t.status),statusTone(t.status))}<h2 style="margin:16px 0">${esc(t.title)}</h2>${paseoAttemptActions(t,t.attempts.length-1)}<div class="od-row" style="flex-wrap:wrap;margin-bottom:20px">${badge(t.mode==='scrum'?'Scrum · '+t.role:'SLP · Peer')}${badge('Cost '+money(t.cost))}${badge(t.attempts.includes('green')?'Gate green':'Gate pending',t.attempts.includes('green')?'green':'')}${badge('Eye '+(t.attempts.includes('green')?'CLEAR':'Pending'))}${badge('Watch '+(t.attempts.includes('green')?'0.08':'—'))}</div><h3>Contract</h3><dl class="data-list" style="margin:20px 0"><div><dt>Gate</dt><dd class="mono">npm run check</dd></div><div><dt>Artifact</dt><dd>${esc(t.artifact)}</dd></div><div><dt>Scope</dt><dd>Assigned task worktree</dd></div><div><dt>Skills</dt><dd>code-review · tdd</dd></div><div><dt>Workspace</dt><dd>${esc(t.project)}</dd></div><div><dt>Created by</dt><dd>Lead · Watch on</dd></div></dl><p class="small muted">Sample Contract. Deliver the named artifact within the assigned scope and attach a reproducible verification report.</p><div class="rule"></div><h3>Attempts</h3>${t.attempts.length?t.attempts.map((s,i)=>`<details style="margin:16px 0"><summary class="small">#${i+1} · ${s==='green'?'Gate green':s==='red'?'Gate red':'Open attempt'} ${i?'· Respawned':''}</summary>${paseoAttemptActions(t,i)}<div class="notice" style="margin-top:12px">${s==='green'?'Sample verification passed. Fresh-eyes: CLEAR. Watch: low concern.':s==='red'?'Sample attempt failed its gate. A targeted repair was requested.':'The agent is working. Verification evidence is not available yet.'}</div><h3>Report.md</h3><pre>${esc(sampleReport(t,s))}</pre>${button('Copy report','copy',`data-copy="${esc(sampleReport(t,s))}"`,'','copy')}<h3 style="margin-top:20px">Gate log</h3><pre>${s==='green'?'Sample gate exit: 0\nVerification complete.':s==='red'?'Sample gate exit: 1\nOne bounded finding requires repair.':'Awaiting gate execution.'}</pre>${button('Copy log','copy',`data-copy="${s==='green'?'Sample gate exit: 0':'Awaiting gate evidence'}"`,'','copy')}</details>`).join(''):'<div class="empty">No attempts yet. Waiting for prerequisites.</div>'}<div class="dialog-actions">${button('Close','close-modal','','ghost')}${t.status==='ready'?button('Accept #'+t.attempts.length,'accept',`data-task="${t.id}" ${readonly()?'disabled':''}`,'primary'):''}</div>`,true);}
function sampleReport(t,s){return `# ${t.id} — sample report\n\nTask: ${t.title}\nArtifact: ${t.artifact}\nVerdict: ${s}\n\nThis is illustrative evidence for the interactive prototype, not a real execution report.`;}
function renderInbox(){const scrum=readonly()||mode()==='scrum';const hasDesign=scrum&&!state.designDecision,hasQuestion=scrum&&!state.questionAnswer&&!state.cancelledQuestion;const pending=scopedTasks().filter(t=>t.status==='attention'||(t.mode==='slp'&&t.status==='ready'));return `<div class="inbox-grid"><div>${hasDesign?`<article class="panel inbox-item"><div class="od-row">${badge('UI APPROVAL','amber',true)}<span class="spacer"></span><span class="small muted">UX Designer · SCR-02</span></div><h2>A new workspace design is ready</h2><p>Review the agent graph, task inspection, and Owner decision flow. Delivery stays behind the UI gate until your decision is recorded.</p><div class="od-row">${badge('Design r3')}${badge('sample-digest-03')}<span class="spacer"></span>${button('Review design','review',readonly()?'disabled':'','primary','design')}</div></article>`:''}${hasQuestion?`<article class="panel inbox-item"><div class="od-row">${badge('QUESTION','cyan')}<span class="spacer"></span><span class="small muted">Architect · REQ-02</span></div><h2>Should the graph keep completed agents visible?</h2><p>Recommendation: keep completed agents visible, with a compact state. The retention policy is held until you answer; independent architecture work continues.</p>${button('Answer question','question',readonly()?'disabled':'','','arrow')}</article>`:''}${pending.map(t=>`<article class="panel inbox-item">${badge(t.status==='ready'?'READY TO ACCEPT':'BLOCKER',t.status==='ready'?'green':'amber')}<h2>${esc(t.title)}</h2><p>${esc(t.blocker||'The latest attempt is green and ready for Owner acceptance.')}</p>${button('Inspect task','task',`data-task="${t.id}"`)} ${t.status==='ready'?button('Accept attempt','accept',`data-task="${t.id}" ${readonly()?'disabled':''}`,'primary'):button('Open Peer','open-agent',`data-agent-id="${t.agent}"`,'','external')}</article>`).join('')}${!hasDesign&&!hasQuestion&&!pending.length?'<div class="panel empty"><h3>You’re all caught up</h3><p>No decisions or green attempts are waiting for you.</p></div>':''}${state.cancelledQuestion?'<div class="notice">REQ-02 cancelled. The completed-agent retention decision remains held until the Supervisor resolves it.</div>':''}</div><aside class="panel allowance"><span class="eyebrow">WORK ALLOWANCE</span><h2 style="margin-top:8px">Room to keep moving</h2><div class="amount"><span class="muted">Tasks used</span><strong>${state.tasks.filter(t=>t.mode==='scrum').length} / ${state.allowance}</strong></div><div class="progress"><span style="width:${Math.min(100,state.tasks.filter(t=>t.mode==='scrum').length/state.allowance*100)}%"></span></div><div class="amount"><span class="muted">Automatic QA fixes</span><strong>${state.fixRounds} / ${state.qaAllowance}</strong></div><div class="progress"><span style="width:${state.fixRounds/state.qaAllowance*100}%"></span></div><p class="small muted" style="margin:20px 0;line-height:1.8">Owner review has no expiry. Elapsed time is informational and does not consume your allowance.</p>${button('Add work allowance','allowance',readonly()?'disabled':'','','plus')}${button('Add 1 QA fix round','qa-allowance',readonly()?'disabled':'','ghost','plus')}</aside></div>`;}
function review(){if(readonly())return notify('Select a project to record a decision.',true);openModal('UI Mockup Preview & Approval',`<div class="od-row" style="flex-wrap:wrap">${badge('Design r3 · sample-digest-03')}${badge(state.designDecision?'Decision recorded':'Awaiting your decision',state.designDecision?'green':'amber')}</div><p class="small muted" style="margin:16px 0">Stage 4 remains held until readiness and Owner approval are satisfied. This embedded sample represents the review layout; it is not verified design evidence.</p><div class="toolbar"><div class="filters"><button class="filter active" data-viewport="desktop">Desktop</button><button class="filter" data-viewport="tablet">Tablet</button><button class="filter" data-viewport="mobile">Mobile</button></div><label class="small">Screen <select id="review-screen"><option>Workspace overview</option><option>Task detail</option><option>Owner inbox</option></select></label><label class="small">State <select id="review-state"><option>Needs approval</option><option>Running</option><option>Empty</option></select></label></div><div class="preview-frame" id="review-preview"><div class="preview-mini-nav"><i></i><i></i><i></i><i></i></div><div class="preview-mini-content"><h3 id="preview-title">Workspace overview</h3><p id="preview-state">Needs approval · sample layout</p><div class="preview-cells"><div>Supervisor</div><div>Lead</div><div>Agents</div></div></div></div><div class="small muted" id="review-dimensions">Desktop · fluid preview · no verified captures supplied</div><div class="rule"></div><div class="field"><label for="rationale">Decision rationale <span class="amber">*</span></label><textarea id="rationale" placeholder="Explain the decision and any required changes…" ${state.designDecision?'disabled':''}></textarea><span class="error" id="decision-error" hidden>Add a rationale before recording your decision.</span></div><div class="dialog-actions">${button('Open Design Studio','studio','','ghost','external')}${button('Waive','decision','data-decision="waive" '+(state.designDecision?'disabled':''))}${button('Request Changes','decision','data-decision="changes" '+(state.designDecision?'disabled':''))}${button('Approve','decision','data-decision="approve" '+(state.designDecision?'disabled':''),'primary','check')}</div>`,true);}
function showQuestion(){openModal('Answer Architect · REQ-02','<p>Should the graph keep completed agents visible? Only the retention policy is waiting for this decision.</p><div class="field"><label for="question-answer">Answer or cancellation reason <span class="amber">*</span></label><textarea id="question-answer" placeholder="Keep completed agents visible in compact form…"></textarea><span class="error" id="question-error" hidden>Enter an answer or a cancellation reason.</span></div><div class="dialog-actions">'+button('Cancel question','record-question','data-cancel="yes"')+button('Record answer','record-question','','primary')+'</div>');}
function showAllowance(){openModal('Add work allowance','<p>Add capacity to this run without resetting attempts or accepted history.</p><div class="field"><label for="additional-tasks">Additional Tasks</label><input id="additional-tasks" type="number" min="1" max="1000" value="8"></div><div class="field"><label for="allowance-reason">Allowance or continuation rationale <span class="amber">*</span></label><textarea id="allowance-reason"></textarea><span class="error" id="allowance-error" hidden>Enter a whole number from 1 to 1000 and a rationale.</span></div><div class="dialog-actions">'+button('Cancel','close-modal')+button('Add Tasks','grant-allowance','','primary')+'</div>');}
function openAgent(id){const a=agent(id);openModal('Open in Paseo',`<p><strong>${esc(a.name)}</strong> opens in its native Paseo conversation. This sample workspace has no live session connection, so no navigation or agent operation is sent.</p><pre>${esc('sample-'+id+'-03')}</pre><p>Supervisor starts from <strong>New Chat → Supervisor (Factory)</strong>. Lead is spawned by Supervisor.</p><div class="dialog-actions">${button('Copy sample session ID','copy',`data-copy="sample-${esc(id)}-03"`,'','copy')}${button('Close','close-modal','','primary')}</div>`);}
async function copyText(text){try{await navigator.clipboard.writeText(text);notify('Copied to clipboard.');}catch{openModal('Copy text',`<p>Clipboard access is unavailable here. Select and copy the text below.</p><textarea readonly aria-label="Text to copy">${esc(text)}</textarea>`);$('#modal-body textarea').select();}}
// Configuration is deliberately separate from the frozen sample run roster.
state.nextModels={};
function laneConfig(id){return state.nextModels[scopeKey()+':'+mode()+':'+id]||{provider:agent(id).provider,model:agent(id).model,thinking:'High'};}
function renderModels(){const ids=mode()==='scrum'?['supervisor','lead','pm','ux','architect','dev','qa','watch']:['supervisor','lead','dev','watch'];return `<div class="notice">${mode()==='scrum'?'Run roster is locked at revision r3. Saved changes apply to the next run.':'Lane changes are copied to this project. Live seat changes require confirmation.'}</div><div class="panel profile-strip"><span class="small muted">${mode()==='scrum'?'Scrum Profiles':'Lane Profiles'}</span>${state.profiles.filter(p=>p.mode===mode()).map(p=>`<button class="filter ${state.profile===p.name?'active':''}" data-action="apply-profile" data-profile="${esc(p.name)}" ${readonly()?'disabled':''}>${esc(p.name)}</button>`).join('')||'<span class="small muted">No saved profiles</span>'}<span class="spacer"></span>${button('Save Profile…','save-profile',readonly()?'disabled':'','','plus')}${button('Reset to Machine Default','reset-lanes',readonly()?'disabled':'','ghost')}</div>${mode()==='scrum'?`<div class="panel content-card switch-row" style="margin-bottom:20px"><div><h3>Require UI Approval</h3><p>Hold implementation for your revision-bound design decision.</p></div><button class="switch ${state.approval?'on':''}" role="switch" aria-checked="${state.approval}" aria-label="Require UI Approval" data-action="toggle-approval" ${readonly()?'disabled':''}></button></div>`:''}<div class="list-grid">${ids.map((id,i)=>{const a=agent(id),c=laneConfig(id);return `<article class="panel content-card"><div class="card-top"><span class="role-avatar ${statusTone(a.status)}">${a.initials}</span>${badge(mode()==='scrum'?['Authority','Coordinator','Planning','Design','Design','Delivery','Verification','Feedback'][i]:['Authority','Coordinator','Coding Workhorse','Feedback'][i])}</div><h3>${id==='dev'&&mode()==='slp'?'Default Worker':esc(a.name)}</h3><p>${esc(a.subtitle)}${id==='watch'?' · one model for Watch and Retro':''}</p><dl class="data-list"><div><dt>Provider</dt><dd>${esc(c.provider)}</dd></div><div><dt>Model</dt><dd>${esc(c.model)}</dd></div><div><dt>Thinking</dt><dd>${esc(c.thinking)}</dd></div></dl><div class="card-actions">${button('Configure','configure',`data-role="${id}" ${readonly()?'disabled':''}`,'','settings')}${['supervisor','lead'].includes(id)?button(id==='lead'?'Rotate Lead':'Revoke Supervisor','retire-seat',`data-role="${id}" ${readonly()?'disabled':''}`,'ghost'):''}</div></article>`;}).join('')}</div>`;}
function configureLane(id){const a=agent(id),c=laneConfig(id);openModal(`Configure ${a.name} Lane`,`<p>Sample provider catalogue. You may also enter a custom model ID. ${mode()==='scrum'?'This applies to the next run.':''}</p><div class="field"><div class="paseo-provider-label"><label for="lane-provider">Provider</label>${paseoSettingsShortcut('providers')}</div><select id="lane-provider">${['Codex','Claude','Pi','OpenCode'].map(x=>`<option ${x===c.provider?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="lane-search">Search sample models</label><input id="lane-search" placeholder="Filter model names…"></div><div class="filters" id="lane-options" style="margin-bottom:18px">${['GPT-6.1','Claude Sonnet','GLM-5.3'].map(x=>`<button class="filter" data-action="pick-model" data-model="${x}">${x}</button>`).join('')}</div><div class="field"><label for="lane-model">Model ID</label><input id="lane-model" value="${esc(c.model)}"></div><div class="field"><label for="lane-thinking">Thinking level</label><select id="lane-thinking">${['Provider default','Off','Minimal','Low','Medium','High','Max'].map(x=>`<option ${x===c.thinking?'selected':''}>${x}</option>`).join('')}</select><small>Available reasoning levels depend on the selected provider and model.</small><span class="error" id="lane-error" hidden>Enter a model ID before saving.</span></div><div class="dialog-actions">${button('Cancel','close-modal')}${button('Save lane','save-lane',`data-role="${id}"`,'primary')}</div>`);}
function renderActivity(){const list=state.events.filter(e=>!state.search||(e.text+' '+e.task).toLowerCase().includes(state.search.toLowerCase()));return `<div class="tabs">${[['usage','Usage'],['retro','Daily Retro'],['ledger','Ledger Stream']].map(([id,name])=>`<button class="tab ${state.activityTab===id?'active':''}" data-activity-tab="${id}">${name}</button>`).join('')}</div>${state.activityTab==='usage'?renderUsage():state.activityTab==='retro'?`<div class="toolbar"><p class="small muted">Feedback proposals require Supervisor ratification.</p>${button('Run Retro','run-retro',readonly()?'disabled':'','','refresh')}</div>${state.retro.length?state.retro.map((r,i)=>`<article class="panel content-card" style="margin-bottom:16px"><div class="card-top"><h3>Daily Retro ${i+1}</h3>${badge('Sample · written','green')}</div><p>Model: ${esc(laneConfig('watch').model)} · 1 proposal</p><div class="notice"><strong>R${i+1} · Workflow</strong><p class="small" style="margin-top:8px">Keep completed specialist nodes compact so active work and Owner decisions remain prominent.</p></div><div class="card-actions">${button('Copy','copy','data-copy="Keep completed specialist nodes compact so active work remains prominent."','','copy')}${button(r.ratified?'Recorded via Supervisor':'Ratify via Supervisor','ratify',`data-retro="${i}" ${r.ratified||readonly()?'disabled':''}`)}</div></article>`).join(''):'<div class="panel empty"><h3>No retro has run yet</h3><p>Run a sample Retro to see the proposal and ratification flow.</p></div>'}`:`<div class="toolbar"><span class="small muted">${list.length} entries · 40 most recent</span><label class="sr-only" for="ledger-search">Filter ledger</label><input class="search-input" id="ledger-search" placeholder="Filter task, event, or content…" value="${esc(state.search)}"></div><div class="panel content-card">${list.length?list.slice(0,40).map((e,i)=>`<div class="ledger-row"><span class="muted">#${state.events.length-i}</span><span class="cyan">${esc(e.task||'workspace')}</span><span>${esc(e.text)}</span></div>`).join(''):'<div class="empty">No matching ledger events.</div>'}</div>`}`;}
function renderTimeline(){const minutes=({'30m':30,'2h':120,'6h':360,'24h':1440})[state.period];const tasks=scopedTasks();const ids=[...new Set(['supervisor','lead',...tasks.filter(t=>t.attempts.length).map(t=>t.agent)])];return `<div class="toolbar"><span class="small muted">Agent swimlanes · sample execution window</span><div class="filters">${['30m','2h','6h','24h'].map(p=>`<button class="filter ${state.period===p?'active':''}" data-period="${p}">${p}</button>`).join('')}</div></div><div class="panel content-card"><div class="timeline-axis">${[1,.75,.5,.25,0].map(f=>`<span>${f?'-'+Math.round(minutes*f)+'m':'Now'}</span>`).join('')}</div>${ids.map((id,i)=>{const a=agent(id),duration=Math.min(minutes,14+i*7),offset=Math.max(0,minutes-duration-(i*3%12));return `<div class="timeline-row"><span class="od-field"><strong>${esc(a.name)}</strong><small class="muted">${esc(a.task||'Standing seat')}</small></span><div class="timeline-track"><span style="width:${offset/minutes*100}%"></span><i class="${a.status==='completed'?'done':a.status==='attention'?'wait':''}" style="width:${duration/minutes*100}%" title="Sample activity: ${duration} minutes"></i></div><span class="${statusTone(a.status)}">${statusLabel(a.status)}</span></div>`;}).join('')}<h3 style="margin-top:28px">Task attempts</h3>${tasks.filter(t=>t.attempts.length).map(t=>`<div class="timeline-row"><button class="text-btn" data-action="task" data-task="${t.id}">${t.id}</button><span class="attempts">${t.attempts.map(s=>`<i class="dot ${s==='green'?'green':s==='red'?'red':'cyan'}"></i>`).join('')}</span><span class="muted">${t.attempts.length} att</span></div>`).join('')}</div>`;}
function renderIntegrations(){return `<div class="tabs">${[['plugins','Plugins & Tools'],['skills','Skill Hub'],['mcps','Helper MCP Servers']].map(([id,label])=>`<button class="tab ${state.integrationTab===id?'active':''}" data-integration-tab="${id}">${label}</button>`).join('')}</div>${state.integrationTab==='plugins'?renderPlugins():state.integrationTab==='skills'?renderSkills():renderMcps()}`;}
function renderPlugins(){const missing=state.plugins.filter(p=>p.protected&&!p.installed);return `${missing.length?`<div class="panel content-card setup-gate"><span class="eyebrow amber">PREREQUISITE SETUP GATE</span><h3 style="margin:8px 0">Required Factory Skills & Tools Setup</h3><p>${missing.length} required component(s) missing or incomplete.</p>${button('Install Required Skills & Tools','install-required',readonly()?'disabled':'','primary')}</div>`:''}<div class="toolbar"><div><h2>Factory plugins</h2><p class="small muted" style="margin-top:4px">Core + ${state.plugins.length-1} companions · ${state.plugins.filter(p=>p.enabled&&p.installed).length} active in sample</p></div>${button('Check for updates','check-updates','','','refresh')}</div><div class="list-grid">${state.plugins.map(p=>`<article class="panel content-card"><div class="card-top">${badge(p.tag)}${badge(p.installed?p.enabled?'Running':'Disabled':'Not Installed',p.enabled&&p.installed?'green':'')}</div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="small mono muted">${esc(p.id)} · ${esc(p.version)} · sample status</div><div class="card-actions">${button(p.installed?'Manage':'Install','manage-plugin',`data-plugin="${p.id}" ${readonly()?'disabled':''}`,'','plug')}${p.protected?badge('Protected',''):''}</div></article>`).join('')}</div>`;}
function managePlugin(id){const p=state.plugins.find(p=>p.id===id);openModal(`Manage ${p.name}`,`<div class="od-row">${badge(p.tag)}${badge('Sample configuration')}</div><p style="margin-top:20px">${esc(p.description)} ${p.protected?'This required component cannot be disabled or removed.':''}</p><dl class="data-list"><div><dt>Source</dt><dd>Canonical GitHub source</dd></div><div><dt>Version</dt><dd>${esc(p.version)}</dd></div><div><dt>Capabilities</dt><dd>${id==='core'?'Factory shell · Contracts · Gates':id==='design'?'Design Studio · UI approval':'Artifact checks'}</dd></div></dl><div class="rule"></div><div class="field"><label for="plugin-source">Custom source</label><input id="plugin-source" placeholder="owner/repository"></div><div class="field"><label for="plugin-ref">Ref</label><input id="plugin-ref" value="main"></div><div class="dialog-actions">${button('Switch source','plugin-op',`data-plugin="${id}" data-op="source"`)}${button('Reload','plugin-op',`data-plugin="${id}" data-op="reload"`)}${button('Update','plugin-op',`data-plugin="${id}" data-op="update"`)}${button(p.enabled?'Disable':'Enable','plugin-op',`data-plugin="${id}" data-op="toggle" ${p.protected?'disabled':''}`)}${button('Remove','plugin-op',`data-plugin="${id}" data-op="remove" ${p.protected?'disabled':''}`,'danger')}${!p.installed?button('Install','plugin-op',`data-plugin="${id}" data-op="install"`,'primary'):''}</div>`);}
function renderSkills(){const installed=state.skills.filter(s=>s.installed);return `<div class="toolbar"><div><h2>Skill Hub</h2><p class="small muted">${installed.length} installed · 5/5 harnesses linked in sample</p></div><div class="od-row">${button('Update Skills','update-skills',readonly()?'disabled':'','','refresh')}${button('Heal Symlinks','heal-skills',readonly()?'disabled':'','ghost')}</div></div><div class="list-grid" style="margin-bottom:24px">${['Expo','Firebase','3D/ZCode','Science'].map(pack=>`<article class="panel content-card"><div class="card-top"><h3>${pack}</h3>${badge(state.linkedPacks.includes(pack)?'Enabled':'Available',state.linkedPacks.includes(pack)?'green':'')}</div><p>Project-scoped ${pack} skills and workflows.</p>${button(state.linkedPacks.includes(pack)?'Enabled — disable':'Enable for Project','toggle-pack',`data-pack="${pack}" ${readonly()?'disabled':''}`)}</article>`).join('')}</div><div class="tabs">${[['installed','Installed in Factory'],['host','Host Ecosystems'],['matrix','Role ↔ Skill Matrix']].map(([id,label])=>`<button class="tab ${state.skillTab===id?'active':''}" data-skill-tab="${id}">${label}</button>`).join('')}</div>${state.skillTab==='matrix'?`<div class="list-grid">${['Supervisor','Lead','Peer','PM','UX','Architect','Dev','QA'].map(role=>`<article class="panel content-card"><h3>${role}</h3><p>${state.skills.filter(s=>s.installed&&(s.role.includes(role)||['Supervisor','Lead','Peer'].includes(role))).map(s=>s.name).join(' · ')||'No role-wide skills assigned'}</p><span class="small muted">Task-specific skills are attached to each Contract.</span></article>`).join('')}</div>`:state.skillTab==='host'?`<div class="panel content-card"><h3>Available on host · sample catalogue</h3><p class="small muted" style="margin:12px 0">Import copies the skill to Factory and links the configured harnesses.</p>${state.skills.filter(s=>!s.installed).map(s=>`<div class="toolbar"><div><strong class="small">${esc(s.name)}</strong><p class="small muted">${s.pack} · Available on Host</p></div>${button('+ Import to Factory','import-skill',`data-skill="${s.name}" ${readonly()?'disabled':''}`)}</div>`).join('')||'<div class="empty">All sample skills have been imported.</div>'}</div>`:`<div class="toolbar"><label class="sr-only" for="skill-search">Search installed skills</label><input class="search-input" id="skill-search" value="${esc(state.search)}" placeholder="Search installed skills…"></div><div class="panel table-wrap"><table><thead><tr><th>SKILL</th><th>PACK</th><th>STATUS</th><th>ROLES</th></tr></thead><tbody>${installed.filter(s=>(s.name+' '+s.pack).toLowerCase().includes(state.search.toLowerCase())).map(s=>`<tr><td>${esc(s.name)}</td><td>${s.pack}</td><td>${badge('Up to Date','green')}</td><td class="muted">${s.role}</td></tr>`).join('')||'<tr><td colspan="4">No matching installed skills.</td></tr>'}</tbody></table></div>`}`;}
function renderMcps(){return `<div class="toolbar"><div><h2>Helper MCP Servers ${badge('PEER ONLY')}</h2><p class="small muted">${state.mcps.filter(m=>m.synced).length} synced · ${state.mcps.length} local in sample catalogue</p></div>${button('Check Connectivity','probe-mcps',readonly()?'disabled':'','','refresh')}</div><div class="notice">Helper servers are provisioned for task Peers. Connectivity in this prototype is illustrative; no host credentials are accessed.</div><div class="list-grid">${state.mcps.map((m,i)=>`<article class="panel content-card"><div class="card-top"><h3>${m.name}</h3>${badge(m.health,m.health==='Sample connected'?'green':'')}</div><p>${m.transport} · ${m.synced?'Synced to Peer':'Available on Host'}</p><div class="filters">${['Pi','Claude','Codex','OpenCode'].map(target=>`<button class="filter ${m.targets.includes(target)?'active':''}" data-action="mcp-target" data-mcp="${i}" data-target="${target}" ${!m.synced||readonly()?'disabled':''}>${target}</button>`).join('')}</div><div class="card-actions">${button(m.synced?'Unsync':'+ Sync to Peer','mcp-sync',`data-mcp="${i}" ${readonly()?'disabled':''}`)}${button('Vault: '+(m.vault?'On':'Off'),'mcp-vault',`data-mcp="${i}" ${!m.synced||readonly()?'disabled':''}`,'ghost')}</div></article>`).join('')}</div>`;}
function renderDesign(){return `<div class="panel content-card"><div class="card-top"><div><span class="eyebrow">PROJECT DESIGN CONNECTION</span><h2 style="margin-top:8px">Factory workspace redesign</h2></div>${badge(state.linkedDesign?'Sample · linked':'Not linked',state.linkedDesign?'cyan':'')}</div><p>Design sources, revisions, and Owner decisions stay connected to the selected project.</p>${state.linkedDesign?`<dl class="data-list"><div><dt>Project</dt><dd>${esc(state.project)}</dd></div><div><dt>Design revision</dt><dd>r3 · sample-digest-03</dd></div><div><dt>Review</dt><dd>${state.designDecision?esc(state.designDecision):'Awaiting Owner'}</dd></div><div><dt>Design evidence</dt><dd>Illustrative layout · no verified capture supplied</dd></div></dl>`:''}<div class="card-actions">${state.linkedDesign?button('Open Design Studio','studio','','primary','external')+button('Sync','sync-design',readonly()?'disabled':'','','refresh')+button('Unlink','unlink-design',readonly()?'disabled':'','ghost'):button('Link Open Design…','link-design',readonly()?'disabled':'','primary','design')}</div></div><div class="notice" style="margin-top:20px">This prototype does not access local design folders. The real integration retains folder authorization, revision freshness, and the in-app Studio fallback.</div>`;}
function renderVault(){return `<div class="settings-grid"><section class="panel content-card"><div class="card-top"><span class="role-avatar cyan">PV</span>${badge('PRIVATE VAULT')}</div><h2>${state.vaultStage===0?'GitHub Login Required':state.vaultStage===1?'Ready to provision private vault':'Vault: '+esc(state.vaultRepo)}</h2><p style="margin:16px 0">${state.vaultStage===0?'Connect GitHub CLI to provision your private configuration repository.':state.vaultStage===1?'Choose a private repository for configuration and signing-key synchronization.':'Configuration and key metadata are ready for your next device.'}</p>${state.vaultStage===0?`<pre class="mono" style="padding:16px;background:var(--bg);border-radius:6px">gh auth login --web -p https</pre><div class="card-actions">${button('Copy Command','copy','data-copy="gh auth login --web -p https"','','copy')}${button('Check GitHub Login','github-login',readonly()?'disabled':'','primary')}</div>`:state.vaultStage===1?`<div class="field"><label for="vault-repository">Repository</label><input id="vault-repository" value="sample-owner/factory-vault"></div>${button('Enable & Sync Vault','enable-vault',readonly()?'disabled':'','primary')}`:`<div class="filters">${badge('Lanes','green')}${badge('Eye','green')}${badge('Apps: '+(state.vaultImported?1:0))}${badge('ASC .p8',state.vaultImported?'green':'')}${badge('GPlay JSON',state.vaultImported?'green':'')}</div><div class="card-actions">${button('Sync Vault','sync-vault',readonly()?'disabled':'','primary','refresh')}${button('+ Import Key','import-key',readonly()?'disabled':'')}${button('Advanced settings','vault-settings',readonly()?'disabled':'','ghost','settings')}</div>`}</section><aside class="panel content-card"><h3>Sample configuration</h3><p>No account login, key import, or GitHub operation is performed. Forms illustrate the flow and keep sample values in memory only.</p><div class="data-list"><div><dt>Node</dt><dd class="mono">sample-machine</dd></div><div><dt>Checkout</dt><dd>${state.vaultStage===2?'sample cached':'none'}</dd></div><div><dt>Last sync</dt><dd>${state.vaultSynced?'Sample · just now':'Not synced'}</dd></div></div></aside></div>`;}
function renderSettings(){return `<div class="settings-grid"><section class="panel content-card"><h2>Project</h2><dl class="data-list" style="margin:24px 0"><div><dt>Name</dt><dd>${esc(state.project)}</dd></div><div><dt>Directory</dt><dd class="mono">${esc(project()?.path||'All projects')}</dd></div><div><dt>Execution mode</dt><dd>${mode()==='scrum'?'Agile Scrum':'SLP'}</dd></div></dl><div class="card-actions">${button('Add Project','add-project','','','plus')}${button('Switch execution mode','switch-mode',readonly()?'disabled':'','ghost')}</div></section><section class="panel content-card"><h2>Daemon & State Diagnostics</h2><dl class="data-list" style="margin:24px 0"><div><dt>Daemon</dt><dd>${badge('Not connected')}</dd></div><div><dt>serverId</dt><dd>Unavailable in prototype</dd></div><div><dt>stateDir</dt><dd>Unavailable in prototype</dd></div><div><dt>Selected project</dt><dd>${esc(state.project)}</dd></div></dl><p>Runtime information will be populated by the Factory snapshot integration.</p></section><section class="panel content-card"><h2>Project actions</h2><p style="margin-top:12px">Reset clears sample work. Delete removes the sample project from this preview. Both require a second confirmation within 5 seconds.</p><div class="card-actions">${button('Reset Project','danger-project',`data-op="reset" ${readonly()?'disabled':''}`,'danger')}${button('Delete Project','danger-project',`data-op="delete" ${readonly()?'disabled':''}`,'danger')}</div></section><section class="panel content-card"><h2>Private Vault</h2><p style="margin-top:12px">Keep your configuration and signing material in a private repository.</p>${button('Open Vault','vault','','','shield')}</section></div>`;}

function selectProject(name){if(name!=='all'&&!state.projects.some(p=>p.name===name))return;state.project=name;state.selected=state.emptyProjects?.has(name)?'owner':mode()==='scrum'?'ux':'peer-1';state.profile=null;closeModal();render();}
function showProjects(){openModal('Switch project',`<div class="command-results"><button class="command-result" data-action="select-project" data-project="all">${icon('folder')}<span class="od-fill">All projects <small class="muted">· View-only</small></span>${badge(state.tasks.length+' tasks')}</button>${state.projects.map(p=>`<button class="command-result" data-action="select-project" data-project="${esc(p.name)}"><span class="project-avatar">${esc(p.name.slice(0,2))}</span><span class="od-field od-fill"><strong>${esc(p.name)}</strong><small class="muted">${p.mode==='scrum'?'Agile Scrum':'SLP'} · ${esc(p.path)}</small></span>${icon('chevron')}</button>`).join('')}</div><div class="dialog-actions">${button('+ Add Project','add-project')}</div>`);}
const commands=[['Factory: Open Verification Board','flow','flow'],['Factory: Open Workspace Panel','flow','folder'],['Factory: Run Daily Retro','retro','refresh'],['Factory: Sync Private Vault','vault','shield'],['Tasks','tasks','tasks'],['Needs you','inbox','inbox'],['Agents & Models','models','agents'],['Plugins & Skills','integrations','plug'],['Open Design','design','design'],['Project settings','settings','settings']];
function commandResults(query=''){const q=query.toLowerCase();const items=commands.filter(([name])=>name.toLowerCase().includes(q));const tasks=state.tasks.filter(t=>(t.id+' '+t.title).toLowerCase().includes(q));return items.map(([name,page,glyph])=>`<button class="command-result" data-action="command" data-page="${page}">${icon(glyph)}<span class="od-fill">${name}</span>${icon('arrow')}</button>`).join('')+(q?tasks.slice(0,5).map(t=>`<button class="command-result" data-action="task" data-task="${t.id}">${icon('tasks')}<span class="od-field"><strong class="small">${t.id}</strong><span class="small muted">${esc(t.title)}</span></span></button>`).join(''):'')||'<div class="empty">No results. Try “tasks”, “retro”, or an existing task ID.</div>';}
function showCommands(){openModal('Command center',`<div class="field"><label for="command-search">Search pages, commands, and tasks</label><input id="command-search" placeholder="Type a command or task ID…" autocomplete="off"></div><div class="command-results" id="command-results">${commandResults()}</div>`);}
function requestMode(next){if(readonly())return;if(next===mode())return;openModal('Switch Project execution mode?',`<p>Project: <strong>${esc(state.project)}</strong> (${mode()==='scrum'?'Agile Scrum':'SLP'} → ${next==='scrum'?'Agile Scrum':'SLP'})</p><div class="notice amber"><strong>Destructive lifecycle change:</strong> The current Supervisor and Lead sessions will be archived, and active seats will be reset. The next Supervisor must be started through New Chat.</div><p class="small muted">Execution mode changes are restricted to Project Settings to prevent accidental mid-run resets. This preview updates sample state only.</p><div class="dialog-actions">${button('Cancel','close-modal')}${button('Archive seats & Switch','confirm-mode',`data-next-mode="${next}"`,'danger')}</div>`);}
function destructive(title,description,operation,payload){openModal(title,`<p>${esc(description)}</p><p class="small muted">Sample data only. The second confirmation expires after 5 seconds.</p><div class="dialog-actions">${button('Cancel','close-modal')}${button('Continue','arm-confirm',`data-operation="${esc(operation)}" data-payload="${esc(payload)}"`,'danger')}</div>`);}
function saveLane(id,config){state.nextModels[scopeKey()+':'+mode()+':'+id]=config;state.profile=null;log(`Next-run ${agent(id).name} lane updated`);closeModal();render();notify('Lane saved in sample configuration. Current run roster remains unchanged.');}
function vaultImport(){openModal('Import Key',`<p>Sample metadata only. No file is opened or uploaded. Use example paths and values.</p>${[['ASC .p8 path','asc-path'],['ASC Key ID','asc-id'],['ASC Issuer ID','asc-issuer'],['Google Play JSON path','play-path'],['Eye config path','eye-path'],['App Key','app-key'],['Android Keystore path','keystore-path'],['Keystore Password','keystore-password']].map(([label,id])=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${id==='keystore-password'?'password':'text'}" placeholder="Sample ${label.toLowerCase()}" autocomplete="off"></div>`).join('')}<span class="error" id="import-error" hidden>Enter at least one sample key path.</span><div class="dialog-actions">${button('Close','close-modal')}${button('Import & Sync','save-import','','primary')}</div>`);}
function artifact(file){openModal(file,`<p>Sample artifact reference for the redesign. No live project file is read by this prototype.</p><pre>${esc(file==='architecture.md'?'# Event and graph projection\n\nKeep authority, workflow dependencies, and task verification as distinct relationships.\nPreserve immutable task/run bindings.\nIndependent work continues while an Owner decision holds dependent work.':file==='DESIGN.md'?'# Factory workspace\n\nGraphite surfaces, restrained cyan accents, clear hierarchy.\nThe Flow Board is the primary operational surface.\nTask and agent details open without losing graph context.':file==='EXPERIENCE.md'?'# Owner workflow\n\nFind the active agent, inspect its task, and resolve the pending decision.\nOpen native agent conversations in Paseo.\nKeep review waits durable and non-expiring.':file==='prd.md'?'# Factory requirements\n\nVisualize SLP and Agile Scrum execution.\nKeep verification and Owner acceptance explicit.\nPreserve models, profiles, integrations, and project controls.':'Sample artifact reference: '+file+'\n\nThe connected application supplies the actual source and verification evidence.')}</pre><div class="dialog-actions">${button('Close','close-modal','','primary')}</div>`);}

document.addEventListener('click',async event=>{
 const el=event.target.closest('button');if(!el||el.disabled)return;
 if(el.dataset.nav){if($('#modal').open)closeModal();navigate(el.dataset.nav);return;}
 if(el.dataset.mode){requestMode(el.dataset.mode);return;}
 if(el.dataset.agent){if(typeof openAgentDrawer==='function'){openAgentDrawer(el.dataset.agent,el);return;}state.selected=el.dataset.agent;state.inspector=true;render();$(`[data-agent="${state.selected}"]`)?.focus({preventScroll:true});return;}
 if(el.dataset.filter){state.filter=el.dataset.filter;render();$(`[data-filter="${state.filter}"]`)?.focus({preventScroll:true});return;}
 if(el.dataset.graphTab){state.graphTab=el.dataset.graphTab;render();$(`[data-graph-tab="${state.graphTab}"]`)?.focus({preventScroll:true});return;}
 if(el.dataset.activityTab){state.activityTab=el.dataset.activityTab;state.search='';render();return;}
 if(el.dataset.integrationTab){state.integrationTab=el.dataset.integrationTab;state.search='';render();return;}
 if(el.dataset.skillTab){state.skillTab=el.dataset.skillTab;state.search='';render();return;}
 if(el.dataset.period){state.period=el.dataset.period;render();return;}
 if(el.dataset.viewport){$$('[data-viewport]').forEach(x=>x.classList.toggle('active',x===el));$('#review-preview').style.width=({desktop:'100%',tablet:'68%',mobile:'320px'})[el.dataset.viewport];$('#review-dimensions').textContent=el.textContent+' · fluid preview · no verified captures supplied';return;}
 const action=el.dataset.action;if(!action)return;
 if(readonly()&&['accept','decision','record-question','grant-allowance','qa-allowance','save-lane','toggle-approval','confirm-mode','confirm-danger','plugin-op','mcp-sync','mcp-target','mcp-vault','save-profile-confirm','apply-profile','enable-vault','save-import','sync-vault','toggle-pack'].includes(action))return notify('All projects is view-only. Select a project first.',true);
 switch(action){
 case 'menu':$('#app').classList.toggle('menu-open');break;
 case 'projects':showProjects();break;
 case 'select-project':selectProject(el.dataset.project);break;
 case 'commands':showCommands();break;
 case 'command':{const p=el.dataset.page;closeModal();if(p==='retro'){state.activityTab='retro';navigate('activity');}else navigate(p);break;}
 case 'close-modal':closeModal();break;
 case 'inbox':navigate('inbox');break;
 case 'tasks':navigate('tasks');break;
 case 'vault':navigate('vault');break;
 case 'open-supervisor':openAgent('supervisor');break;
 case 'open-agent':openAgent(el.dataset.agentId||'supervisor');break;
 case 'toggle-inspector':state.inspector=!state.inspector;render();break;
 case 'compact':state.compact=!state.compact;render();break;
 case 'zoom-in':case 'zoom-out':case 'fit':{state.zoom=action==='fit'?WORKFLOW_DEFAULT_ZOOM:Math.max(50,Math.min(125,state.zoom+(action==='zoom-in'?5:-5)));render();const canvas=$('#graph-canvas');if(canvas)canvas.style.zoom=state.zoom/100;break;}
 case 'task':showTask(el.dataset.task);break;
 case 'artifact':artifact(el.dataset.file);break;
 case 'copy':await copyText(el.dataset.copy||'');break;
 case 'accept':{const t=findTask(el.dataset.task);if(!t||t.status!=='ready'||t.attempts.at(-1)!=='green')break;t.status='accepted';log(`Owner accepted ${t.id}`,t.id,'green','check');if($('#modal').open)closeModal();render();notify(`${t.id} accepted in sample workspace.`);break;}
 case 'review':case 'studio':review();break;
 case 'decision':{const text=$('#rationale').value.trim();if(!text){$('#decision-error').hidden=false;$('#rationale').focus();break;}if(state.designDecision)break;state.designDecision=el.dataset.decision;state.decisionRationale=text;log(`Owner ${state.designDecision==='approve'?'approved':state.designDecision==='changes'?'requested changes to':'waived'} design r3`,'SCR-02',state.designDecision==='changes'?'amber':'green','design');closeModal();render();notify('Revision-bound decision recorded in the sample. Readiness remains a separate prerequisite.');break;}
 case 'question':showQuestion();break;
 case 'record-question':{const answer=$('#question-answer').value.trim();if(!answer){$('#question-error').hidden=false;$('#question-answer').focus();break;}state.cancelledQuestion=el.dataset.cancel==='yes';state.questionAnswer=answer;log(state.cancelledQuestion?'Owner cancelled REQ-02; held work remains held':'Owner answered Architect REQ-02','SCR-03','green','check');closeModal();render();notify(state.cancelledQuestion?'Question cancelled; the dependent decision remains held.':'Answer recorded in the sample.');break;}
 case 'allowance':showAllowance();break;
 case 'grant-allowance':{const n=Number($('#additional-tasks').value),reason=$('#allowance-reason').value.trim();if(!Number.isInteger(n)||n<1||n>1000||!reason){$('#allowance-error').hidden=false;break;}state.allowance+=n;log(`Owner added ${n} Tasks: ${reason}`);closeModal();render();notify(`${n} Tasks added. Attempts and history preserved.`);break;}
 case 'qa-allowance':openModal('Add 1 automatic QA fix round',`<div class="field"><label for="qa-reason">Continuation rationale <span class="amber">*</span></label><textarea id="qa-reason"></textarea><span class="error" id="qa-error" hidden>Enter a rationale.</span></div><div class="dialog-actions">${button('Cancel','close-modal')}${button('Add 1 QA fix round','grant-qa','','primary')}</div>`);break;
 case 'grant-qa':{const reason=$('#qa-reason').value.trim();if(!reason){$('#qa-error').hidden=false;break;}state.qaAllowance++;log('Owner added 1 automatic QA fix round: '+reason);closeModal();render();notify('One QA fix round added in the sample.');break;}
 case 'configure':configureLane(el.dataset.role);break;
 case 'pick-model':$('#lane-model').value=el.dataset.model;break;
 case 'save-lane':{const id=el.dataset.role,c={provider:$('#lane-provider').value,model:$('#lane-model').value.trim(),thinking:$('#lane-thinking').value};if(!c.model){$('#lane-error').hidden=false;break;}if(['supervisor','lead'].includes(id)){state.pendingLane={id,c};const previous=laneConfig(id);openModal(mode()==='scrum'?'Apply to live Scrum seats?':'Confirm live seat impact',`<p>${esc(agent(id).name)}: ${esc(previous.provider+'/'+previous.model)} → ${esc(c.provider+'/'+c.model)}</p><div class="notice">${previous.provider===c.provider?'Update model in-place: the current session is preserved.':'Retire/Rotate: the old provider session is archived.'} The current Scrum run roster remains frozen.</div><div class="dialog-actions">${button('Cancel','close-modal')}${button('Confirm & Apply','apply-lane','','primary')}</div>`);}else saveLane(id,c);break;}
 case 'apply-lane':if(state.pendingLane){saveLane(state.pendingLane.id,state.pendingLane.c);state.pendingLane=null;}break;
 case 'toggle-approval':state.approval=!state.approval;render();notify('UI approval preference saved for the next sample run.');break;
 case 'save-profile':openModal('Save '+(mode()==='scrum'?'Scrum':'Lane')+' Profile',`<div class="field"><label for="profile-name">Profile name <span class="amber">*</span></label><input id="profile-name" value="${esc(state.profile||'Balanced team')}"></div><div class="field"><label for="profile-description">Description (optional)</label><textarea id="profile-description"></textarea><span class="error" id="profile-error" hidden>Enter a profile name.</span></div><p class="small muted">Snapshot of ${mode()==='scrum'?'8 roles':'6 lanes, grouped into 4 cards'} for this project. Applying a profile copies its values.</p><div class="dialog-actions">${state.profile?button('Delete profile','delete-profile',`data-profile="${esc(state.profile)}"`,'danger'):''}${button('Cancel','close-modal')}${button('Save Profile','save-profile-confirm','','primary')}</div>`);break;
 case 'save-profile-confirm':{const name=$('#profile-name').value.trim();if(!name){$('#profile-error').hidden=false;break;}const ids=mode()==='scrum'?['supervisor','lead','pm','ux','architect','dev','qa','watch']:['supervisor','lead','dev','watch'];const profile={name,mode:mode(),config:Object.fromEntries(ids.map(id=>[mode()+':'+id,{...laneConfig(id)}]))};const i=state.profiles.findIndex(p=>p.mode===mode()&&p.name===name);if(i<0)state.profiles.push(profile);else state.profiles[i]=profile;state.profile=name;closeModal();render();notify('Profile snapshot saved in this preview.');break;}
 case 'apply-profile':{const p=state.profiles.find(p=>p.mode===mode()&&p.name===el.dataset.profile);if(!p)break;Object.entries(p.config).forEach(([key,value])=>state.nextModels[scopeKey()+':'+key]={...value});state.profile=p.name;render();notify('Profile copied to the sample project.');break;}
 case 'delete-profile':destructive('Delete profile?','Delete the saved sample profile. Existing project lane values remain copied.','profile',el.dataset.profile);break;
 case 'reset-lanes':destructive('Reset lane configuration?','Restore the sample machine defaults for the selected mode.','lanes',mode());break;
 case 'retire-seat':destructive(el.dataset.role==='lead'?'Rotate Lead?':'Revoke Supervisor?','Archive this sample seat. Supervisor starts in New Chat; Lead is spawned by Supervisor.','seat',el.dataset.role);break;
 case 'run-retro':state.retro.unshift({ratified:false});log('Sample Daily Retro produced one proposal','','cyan','refresh');render();notify('Sample Retro recorded. No model was called.');break;
 case 'ratify':state.retro[Number(el.dataset.retro)].ratified=true;log('Sample proposal recorded for Supervisor ratification');render();notify('Sample Supervisor handoff recorded. No live message was sent.');break;
 case 'manage-plugin':managePlugin(el.dataset.plugin);break;
 case 'check-updates':if(typeof checkIntegrationUpdates==='function'){checkIntegrationUpdates();break;}notify('Sample catalogue is up to date. No remote update check was made.');break;
 case 'install-required':state.plugins.filter(p=>p.protected).forEach(p=>{p.installed=true;p.enabled=true;});render();notify('Required components marked installed in sample data.');break;
 case 'plugin-op':{const p=state.plugins.find(p=>p.id===el.dataset.plugin),op=el.dataset.op;if(!p)break;if(p.protected&&['toggle','remove'].includes(op))break;if(op==='source'&&!$('#plugin-source').value.trim())return notify('Enter a source repository.',true);if(op==='remove')return destructive('Remove companion?','Remove this companion from the sample workspace.','plugin',p.id);if(op==='toggle')p.enabled=!p.enabled;if(op==='install'){p.installed=true;p.enabled=true;}log(`Sample plugin ${p.name}: ${op}`);closeModal();render();notify('Sample plugin state updated. No host installation or reload occurred.');break;}
 case 'update-skills':case 'heal-skills':notify('Sample skill links are current. No host files were changed.');break;
 case 'toggle-pack':{const pack=el.dataset.pack;if(state.linkedPacks.includes(pack))state.linkedPacks=state.linkedPacks.filter(p=>p!==pack);else{state.linkedPacks.push(pack);state.skills.filter(s=>s.pack===pack).forEach(s=>s.installed=true);}render();notify('Project skill-pack preference updated in sample data.');break;}
 case 'import-skill':{const s=state.skills.find(s=>s.name===el.dataset.skill);if(s)s.installed=true;render();notify('Skill imported in sample catalogue only.');break;}
 case 'probe-mcps':state.mcps.forEach(m=>{m.health=m.synced?'Sample connected':'Not synced';});render();notify('Illustrative connectivity result. No server was contacted.');break;
 case 'mcp-sync':{const m=state.mcps[Number(el.dataset.mcp)];m.synced=!m.synced;m.health='Not checked';render();break;}
 case 'mcp-target':{const m=state.mcps[Number(el.dataset.mcp)],target=el.dataset.target;m.targets=m.targets.includes(target)?m.targets.filter(t=>t!==target):[...m.targets,target];render();break;}
 case 'mcp-vault':state.mcps[Number(el.dataset.mcp)].vault=!state.mcps[Number(el.dataset.mcp)].vault;render();break;
 case 'sync-design':notify('Sample design revision is current. No folder was read.');break;
 case 'unlink-design':state.linkedDesign=false;render();notify('Sample design connection removed.');break;
 case 'link-design':openModal('Link Open Design project',`<p>No local folder is accessed in this prototype. Select the sample project to see the linked state.</p><button class="command-result" data-action="confirm-link">${icon('design')}<span class="od-field"><strong>Factory workspace redesign</strong><small class="muted">Sample project · 3 screens · Graphite design system</small></span></button>`);break;
 case 'confirm-link':state.linkedDesign=true;closeModal();render();break;
 case 'github-login':state.vaultStage=1;render();notify('Sample GitHub-ready state shown. No authentication was performed.');break;
 case 'enable-vault':{const repo=$('#vault-repository').value.trim();if(!/^[^\s/]+\/[^\s/]+$/.test(repo))return notify('Use owner/repository format.',true);state.vaultRepo=repo;state.vaultStage=2;state.vaultSynced=true;render();notify('Sample Vault configured. No GitHub repository was created.');break;}
 case 'sync-vault':state.vaultSynced=true;render();notify('Sample sync complete. No keys or files were transmitted.');break;
 case 'import-key':vaultImport();break;
 case 'save-import':if(!['asc-path','play-path','keystore-path','eye-path'].some(id=>$('#'+id).value.trim())){$('#import-error').hidden=false;break;}state.vaultImported=true;state.vaultSynced=true;closeModal();render();notify('Sample key metadata recorded. No files were read or uploaded.');break;
 case 'vault-settings':openModal('Advanced Vault Settings',`<p>node: sample-machine · checkout: sample cached</p><div class="field"><label for="vault-repo-edit">Repository</label><input id="vault-repo-edit" value="${esc(state.vaultRepo)}"></div><div class="field"><label for="vault-branch">Branch</label><input id="vault-branch" value="${esc(state.vaultBranch)}"></div><div class="field"><label for="vault-passphrase">Passphrase (optional sample)</label><input type="password" id="vault-passphrase" autocomplete="off"></div><div class="dialog-actions">${button('Direct Hydrate (gh api)','hydrate-vault')}${button('Save Config','save-vault-settings','','primary')}</div>`);break;
 case 'hydrate-vault':notify('Sample hydration shown. No GitHub API operation was performed.');break;
 case 'save-vault-settings':{const repo=$('#vault-repo-edit').value.trim(),branch=$('#vault-branch').value.trim();if(!/^[^\s/]+\/[^\s/]+$/.test(repo)||!branch)return notify('Enter owner/repository and a branch.',true);state.vaultRepo=repo;state.vaultBranch=branch;closeModal();render();notify('Sample Vault settings saved in memory.');break;}
 case 'add-project':if(typeof fleetAddProject==='function'){fleetAddProject();break;}openModal('Add Project',`<p>Paste a repository path to add a sample project. The native folder chooser is available in the connected Paseo application.</p><div class="field"><label for="new-project-path">Git repository path</label><input id="new-project-path" placeholder="/path/to/git-repo"><span class="error" id="project-error" hidden>Enter an absolute path with a project name.</span></div><div class="dialog-actions">${button('Cancel','close-modal')}${button('Select Project','save-project','','primary')}</div>`);break;
 case 'save-project':{const path=$('#new-project-path').value.trim().replace(/\/$/,''),name=path.split('/').at(-1);if(!path.startsWith('/')||!name){$('#project-error').hidden=false;break;}if(!state.projects.some(p=>p.name===name))state.projects.push({name,mode:'slp',path});state.emptyProjects=state.emptyProjects||new Set();if(!state.tasks.some(t=>t.project===name))state.emptyProjects.add(scopeKey(name));selectProject(name);notify('Sample project added. The folder was not accessed.');break;}
 case 'switch-mode':requestMode(mode()==='scrum'?'slp':'scrum');break;
 case 'confirm-mode':{const p=project();if(!p)break;state.archived.push({hostId:activeHostId(),project:p.name,mode:p.mode});p.mode=el.dataset.nextMode;state.emptyProjects=state.emptyProjects||new Set();state.emptyProjects.add(scopeKey(p.name));state.selected='owner';log(`Sample project switched to ${p.mode}; standing seats archived`);closeModal();render();notify('Mode switched in the sample. Start the next Supervisor from New Chat.');break;}
 case 'danger-project':destructive(el.dataset.op==='delete'?'Delete Project?':'Reset Project?',`${el.dataset.op==='delete'?'Remove':'Clear tasks and seats for'} ${state.project} in this sample workspace.`,'project-'+el.dataset.op,state.project);break;
 case 'arm-confirm':{state.confirmation={operation:el.dataset.operation,payload:el.dataset.payload,scope:scopeKey(),expires:Date.now()+5000};el.textContent='Confirm '+(el.dataset.operation.includes('delete')?'Delete':'action');el.dataset.action='confirm-danger';clearTimeout(confirmationTimer);confirmationTimer=setTimeout(()=>{state.confirmation=null;if(el.isConnected){el.textContent='Confirmation expired';el.disabled=true;}},5000);break;}
 case 'confirm-danger':{const c=state.confirmation;if(!c||Date.now()>c.expires)return notify('Confirmation expired. Reopen the action.',true);if(c.scope&&c.scope!==scopeKey())return notify('The Host or Project changed. Reopen the action.',true);if(c.operation==='profile'){state.profiles=state.profiles.filter(p=>!(p.name===c.payload&&p.mode===mode()));state.profile=null;}if(c.operation==='lanes'){Object.keys(state.nextModels).filter(k=>k.startsWith(scopeKey()+':'+c.payload+':')).forEach(k=>delete state.nextModels[k]);state.profile=null;}if(c.operation==='seat'){state.retiredSeats=state.retiredSeats||new Set();state.retiredSeats.add(scopeKey()+':'+c.payload);}if(c.operation==='plugin')state.plugins=state.plugins.filter(p=>p.id!==c.payload);if(c.operation.startsWith('project-')){state.tasks=state.tasks.filter(t=>!(t.project===c.payload&&(!t.hostId||t.hostId===activeHostId())));state.emptyProjects=state.emptyProjects||new Set();state.emptyProjects.add(scopeKey(c.payload));if(c.operation==='project-delete'){state.projects=state.projects.filter(p=>!(p.name===c.payload&&(!p.hostId||p.hostId===activeHostId())));state.project=state.projects[0]?.name||'all';state.hostId=state.projects[0]?.hostId||'all';}}closeModal();render();notify('Confirmed in sample data. No repository or live session was changed.');break;}
 }
});

document.addEventListener('input',event=>{
 const el=event.target;
 if(el.id==='command-search')$('#command-results').innerHTML=commandResults(el.value);
 if(el.id==='lane-search')$$('[data-model]',$('#lane-options')).forEach(b=>{b.hidden=!b.dataset.model.toLowerCase().includes(el.value.toLowerCase());});
 if(['task-search','ledger-search','skill-search'].includes(el.id)){const pos=el.selectionStart,id=el.id;state.search=el.value;render();const replacement=$('#'+id);replacement?.focus({preventScroll:true});replacement?.setSelectionRange(pos,pos);}
});
document.addEventListener('change',event=>{if(event.target.id==='review-screen')$('#preview-title').textContent=event.target.value;if(event.target.id==='review-state')$('#preview-state').textContent=event.target.value+' · sample layout';});
document.addEventListener('keydown',event=>{
 if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();showCommands();}
 if(event.key==='Escape'&&!$('#modal').open)$('#app').classList.remove('menu-open');
 if(event.key==='Enter'&&event.target.id==='new-project-path'){event.preventDefault();$('[data-action="save-project"]')?.click();}
 if(event.key==='Enter'&&event.target.id==='profile-name'){event.preventDefault();$('[data-action="save-profile-confirm"]')?.click();}
 if(event.key==='Enter'&&event.target.id==='lane-model'){event.preventDefault();$('[data-action="save-lane"]')?.click();}
});
$('#modal').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const box=$('#modal').getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)closeModal();}});
// Keep archived/no-run workspace views separate from seeded active examples.
const fullFlow=renderFlow;
renderFlow=function(){
 if(state.emptyProjects?.has(scopeKey()))return `<div class="notice">No run started. The previous standing seats have been archived, or this project is new.</div><section class="panel"><div class="panel-head"><h2>${mode()==='scrum'?'Scrum':'SLP'} workspace</h2>${badge('No active run')}</div><div class="graph-canvas agent-only">${authorityGraph()}<div class="empty"><h3>Ready for a new direction</h3><p>Select “Supervisor (Factory)” in Paseo’s New Chat. Supervisor will spawn Lead when work is dispatched.</p>${button('Open Paseo handoff','open-supervisor','','','external')}</div></div></section>${renderRecent()}`;
 return fullFlow();
};
const fullInbox=renderInbox;
renderInbox=function(){return state.emptyProjects?.has(scopeKey())?'<div class="panel empty"><h3>No active run</h3><p>Owner decisions will appear after Supervisor dispatches work.</p></div>':fullInbox();};
const fullRender=render;
render=function(){fullRender();const canvas=$('#graph-canvas');if(canvas)canvas.style.zoom=state.zoom/100;};
render();
